    // Handle null strings differently than null suffixes
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null) {
        return false;
    }
    if (suffix == null) {
        return true;
    }
    // Shortcut if the suffix does not contain any characters
    if (suffix.isEmpty()) {
        return true;
    }
    // If the suffix is longer than the string, it cannot be a suffix
    if (suffix.length() > str.length()) {
        return false;
    }
    // If the last characters of the string and the suffix are equals
    // (ignoring case if required), we have a match
    String comp = str.substring(str.length() - suffix.length());
    if (ignoreCase) {
        comp = comp.toLowerCase();
        suffix = suffix.toLowerCase();
    }
    return comp.equals(suffix);
}

