public void generateGraph(Graph<V,E> target,Map<String,V> resultMap) {
    // construct complete bipartite graph
    int numVertices = resultMap.size(); // number of vertices in the complete bipartite graph
    int numEdges = (int) Math.ceil(numVertices / 2.0); // number of edges in the complete bipartite graph

    // add vertices to the graph
    for (String vertexLabel : resultMap.keySet()) {
        target.addVertex(vertexLabel);
    }

    // add edges to the graph
    int edgeCount = 0;
    for (int i = 0; i < numVertices; i++) {
        for (int j = i + 1; j < numVertices; j++) {
            if (edgeCount < numEdges) {
                target.addEdge(resultMap.get(vertexLabels.get(i)), resultMap.get(vertexLabels.get(j)));
                edgeCount++;
            }
        }
    }
