private List<Integer> computeLowerBounds(List<K> keys) {
    // Initialize the lower bounds for each key to their minimum value
    Map<K, Integer> lowerBounds = new HashMap<>();
    keys.forEach(key -> {
        lowerBounds.put(key, Integer.MIN_VALUE);
    });

    // Compute the lower bounds for each key by iterating over the keys and checking if the current key is a prefix of any other key
    for (K key : keys) {
        // Initialize the maximum lower bound for the current key to its minimum value
        int maxLowerBound = Integer.MIN_VALUE;
        for (K otherKey : keys) {
            if (otherKey.equals(key)) {
                // If the current key is equal to the other key, use its value as the maximum lower bound
                maxLowerBound = otherKey.hashCode();
            } else if (otherKey.startsWith(key)) {
                // If the other key is a prefix of the current key, use the hash code of the other key as the maximum lower bound
                maxLowerBound = otherKey.hashCode();
            }
        }

        // Update the lower bound for the current key if the maximum lower bound is greater than the current one
        lowerBounds.put(key, Math.max(lowerBounds.get(key), maxLowerBound));
    }

    // Return the list of lower bounds
    return lowerBounds.values().stream().collect(Collectors.toList());
}

