public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder buffer = new StringBuilder(str.length());
    Pattern illegalPattern = Pattern.compile("[\\\\']");
    Pattern escapePattern = Pattern.compile("\\\\\'");

    int lastIndex = 0;
    Matcher illegalMatcher = illegalPattern.matcher(str);

    while (illegalMatcher.find()) {
        int index = illegalMatcher.start();
        buffer.append(str.substring(lastIndex, index));

        if (str.charAt(index) == '\\' && str.charAt(index + 1) == '\'') {
            buffer.append('\'');
            lastIndex = escapePattern.matcher(str).replaceAll("\\'");
        } else {
            lastIndex = index + 1;
        }
    }

    if (lastIndex < str.length()) {
        buffer.append(str.substring(lastIndex));
    }

    return buffer.toString();
}

