public static String applyRelativePath(String path, String relativePath) {
    // Check for null or empty input
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Invalid input: path and/or relativePath cannot be null or empty");
    }

    // Replace all separators in the input with standard Java folder separators
    path = path.replaceAll("\\\\", "/");
    relativePath = relativePath.replaceAll("\\\\", "/");

    // Extract the directory name and file name from the input paths
    String dirName = path.substring(0, path.lastIndexOf("/"));
    String fileName = path.substring(path.lastIndexOf("/") + 1);
    String relDirName = relativePath.substring(0, relativePath.lastIndexOf("/"));
    String relFileName = relativePath.substring(relativePath.lastIndexOf("/") + 1);

    // Compute the new file path by concatenating the directory name and relative file name
    String newPath = dirName + "/" + relDirName + "/" + relFileName;

    // Replace all separators in the new file path with standard Java folder separators
    newPath = newPath.replaceAll("\\\\", "/");

    return newPath;
}

